  "summary": "The code contained a critical XSS vulnerability, lack of input validation, and hardcoded configuration. I have sanitized the input, enforced type safety, implemented environment-based configuration, and added documentation to improve overall security and maintainability.",
  "fixed_code": "const express = require('express');\nconst escape = require('escape-html');\nconst rateLimit = require('express-rate-limit');\nconst app = express();\n\nconst limiter = rateLimit({\n  windowMs: 15 * 60 * 1000,\n  max: 100\n});\n\n/**\n * @route GET /search\n * @desc Performs a search query\n * @param {string} q - The search term\n */\napp.get('/search', limiter, (req, res) => {\n    const rawQ = typeof req.query.q === 'string' ? req.query.q : '';\n    const q = rawQ.substring(0, 255);\n    res.send('<h1>Results for: ' + escape(q) + '</h1>');\n});\n\napp.listen(process.env.PORT || 3000);"
}
